<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">匹配采购需求</h1><NuxtLink v-for="item in items" :key="item.id" :to="`/supplier/pings/${item.id}`" class="m-card block"><p class="font-semibold text-slate-800">{{ item.title }}</p><p class="mt-1 text-xs text-slate-400">{{ item.status }} · {{ item.matching_listing_ids.length }} matches</p><p class="mt-2 text-xs" :class="item.already_offered?'text-emerald-600':'text-indigo-500'">{{ item.already_offered?'Offer submitted':'Ready to quote' }}</p></NuxtLink><p v-if="error" class="m-card text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const {listSupplierPings}=useCommerce();const items=ref<any[]>([]);const error=ref('');onMounted(async()=>{try{items.value=(await listSupplierPings()).items}catch(e:any){error.value=e?.data?.detail||e?.message}})</script>
